template <bool B>
inline bool VerifyMessageID(::flatbuffers::VerifierTemplate<B> &verifier, const void *obj, MessageID type) {
  switch (type) {
    case MessageID::NONE: {
      return true;
    }
    case MessageID::F_GUEST_MESSAGE_MIN: {
      auto ptr = reinterpret_cast<const F_GUEST_MESSAGE_MIN *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case MessageID::GSCL_CONNECTED_CMD: {
      auto ptr = reinterpret_cast<const GSCL_CONNECTED_CMD *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case MessageID::CLLG_AUTH_REQ: {
      auto ptr = reinterpret_cast<const CLLG_AUTH_REQ *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case MessageID::CLLG_AUTH_ACK: {
      auto ptr = reinterpret_cast<const CLLG_AUTH_ACK *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case MessageID::CLGS_CONNECT_REQ_: {
      auto ptr = reinterpret_cast<const CLGS_CONNECT_REQ_ *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case MessageID::CLGS_CONNECT_ACK_: {
      auto ptr = reinterpret_cast<const CLGS_CONNECT_ACK_ *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case MessageID::CLGS_AUTHEN_REQ: {
      auto ptr = reinterpret_cast<const CLGS_AUTHEN_REQ *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case MessageID::CLGS_AUTHEN_ACK: {
      auto ptr = reinterpret_cast<const CLGS_AUTHEN_ACK *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case MessageID::DBGS_Authentication_REQ: {
      auto ptr = reinterpret_cast<const DBGS_Authentication_REQ *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case MessageID::F_MEMBER_MESSAGE_MAX: {
      auto ptr = reinterpret_cast<const F_MEMBER_MESSAGE_MAX *>(obj);
      return verifier.VerifyTable(ptr);
    }
    default: return true;
  }
}

template <bool B>
inline bool VerifyMessageIDVector(::flatbuffers::VerifierTemplate<B> &verifier, const ::flatbuffers::Vector<::flatbuffers::Offset<void>> *values, const ::flatbuffers::Vector<MessageID> *types) {
  if (!values || !types) return !values && !types;
  if (values->size() != types->size()) return false;
  for (::flatbuffers::uoffset_t i = 0; i < values->size(); ++i) {
    if (!VerifyMessageID(
        verifier,  values->Get(i), types->GetEnum<MessageID>(i))) {
      return false;
    }
  }
  return true;
}

